// AVL Tree — complete insert with rebalancing
class AVLNode {
  constructor(key) {
    this.key    = key;
    this.left   = null;
    this.right  = null;
    this.height = 1;  // leaf height starts at 1
  }
}

class AVLTree {
  #root = null;

  // Height of a node (null = 0)
  #h(n) { return n ? n.height : 0; }

  // Balance factor: positive = left-heavy, negative = right-heavy
  #bf(n) { return n ? this.#h(n.left) - this.#h(n.right) : 0; }

  // Recompute height from children
  #updateH(n) { n.height = 1 + Math.max(this.#h(n.left), this.#h(n.right)); }

  // LL fix: rotate right at y
  //         y                    x
  //        / \      →          / \
  //       x   T3             T1   y
  //      / \                     / \
  //     T1  T2                  T2  T3
  #rotateRight(y) {
    const x  = y.left;
    const T2 = x.right;
    x.right  = y;   // x rises
    y.left   = T2;  // T2 rehomed
    this.#updateH(y);
    this.#updateH(x);
    return x; // new subtree root
  }

  // RR fix: rotate left at x
  #rotateLeft(x) {
    const y  = x.right;
    const T2 = y.left;
    y.left   = x;
    x.right  = T2;
    this.#updateH(x);
    this.#updateH(y);
    return y;
  }

  // Rebalance after insert/delete, returning new subtree root
  #balance(node) {
    this.#updateH(node);
    const bf = this.#bf(node);

    if (bf > 1) {                         // left-heavy
      if (this.#bf(node.left) < 0)        // LR case: left child is right-heavy
        node.left = this.#rotateLeft(node.left);  // reduce to LL
      return this.#rotateRight(node);     // LL case
    }

    if (bf < -1) {                        // right-heavy
      if (this.#bf(node.right) > 0)       // RL case: right child is left-heavy
        node.right = this.#rotateRight(node.right); // reduce to RR
      return this.#rotateLeft(node);      // RR case
    }

    return node; // already balanced
  }

  #insert(node, key) {
    if (!node) return new AVLNode(key);                      // base case
    if      (key < node.key) node.left  = this.#insert(node.left,  key);
    else if (key > node.key) node.right = this.#insert(node.right, key);
    else                     return node;                    // duplicate: no-op
    return this.#balance(node); // fix balance on the way back up
  }

  insert(key) { this.#root = this.#insert(this.#root, key); }
  height()    { return this.#h(this.#root); }

  // Iterative search — no balance needed, just BST property
  search(key) {
    let node = this.#root;
    while (node) {
      if      (key === node.key) return true;
      else if (key  <  node.key) node = node.left;
      else                       node = node.right;
    }
    return false;
  }
}

// Demonstrate that sorted insertion still yields O(log n) height
const avl = new AVLTree();
[1, 2, 3, 4, 5, 6, 7].forEach(k => avl.insert(k));
console.log('height after inserting 1-7 in order:', avl.height()); // 3, not 7
console.log(avl.search(5)); // true
console.log(avl.search(9)); // false

// In a plain BST, inserting 1-7 sorted gives height 7.
// AVL tree rebalances to height ceil(log2(8)) = 3.

// Red-Black Tree invariant checker — verify a tree is valid
// (Useful for testing; this is NOT the tree itself, just the checker)

const RED   = 'red';
const BLACK = 'black';

// Returns the black-height if valid, throws if invariant violated
function checkRBInvariants(node, isRoot = true) {
  // Null nodes are black leaves (base case)
  if (node === null) return 1; // counts as 1 black node on path

  // Invariant 2: root must be black
  if (isRoot && node.color !== BLACK)
    throw new Error(`Root node ${node.key} must be black`);

  // Invariant 4: red node cannot have red children
  if (node.color === RED) {
    if (node.left  && node.left.color  === RED)
      throw new Error(`Red-Red violation at ${node.key} -> ${node.left.key}`);
    if (node.right && node.right.color === RED)
      throw new Error(`Red-Red violation at ${node.key} -> ${node.right.key}`);
  }

  // Invariant 5: left and right black-heights must match
  const leftBH  = checkRBInvariants(node.left,  false);
  const rightBH = checkRBInvariants(node.right, false);
  if (leftBH !== rightBH)
    throw new Error(
      `Black-height mismatch at node ${node.key}: left=${leftBH}, right=${rightBH}`
    );

  // This node's contribution to the black-height of its parent
  return leftBH + (node.color === BLACK ? 1 : 0);
}

// Example: build a minimal valid RB tree by hand and verify it
const root  = { key: 20, color: BLACK, left: null, right: null };
root.left   = { key: 10, color: RED,   left: null, right: null };
root.right  = { key: 30, color: RED,   left: null, right: null };
// Null children of 10 and 30 are black sentinel leaves — OK
try {
  const bh = checkRBInvariants(root);
  console.log('Valid RB tree, black-height:', bh); // Valid RB tree, black-height: 2
} catch(e) {
  console.error('Invariant violated:', e.message);
}

// Now deliberately break invariant 4 (two consecutive reds)
root.left.left = { key: 5, color: RED, left: null, right: null };
try {
  checkRBInvariants(root);
} catch(e) {
  console.error('Caught:', e.message); // Caught: Red-Red violation at 10 -> 5
}

// B+ Tree conceptual simulation — range query on a linked leaf layer
// (Simplified: shows the linked-leaf scan pattern, not full disk-page management)

class Leaf {
  constructor(keys, records) {
    this.keys    = keys;    // sorted array of keys
    this.records = records; // corresponding record data
    this.next    = null;    // linked list pointer to next leaf
    this.prev    = null;
  }
}

// Build a tiny B+ tree leaf layer for demonstration
const leaf1 = new Leaf([5, 10, 15],  ['alice', 'bob',   'carol']);
const leaf2 = new Leaf([20, 25, 30], ['dave',  'eve',   'frank']);
const leaf3 = new Leaf([35, 40, 45], ['grace', 'heidi', 'ivan']);
const leaf4 = new Leaf([50, 55, 60], ['judy',  'karl',  'laura']);

// Link the leaves
leaf1.next = leaf2; leaf2.prev = leaf1;
leaf2.next = leaf3; leaf3.prev = leaf2;
leaf3.next = leaf4; leaf4.prev = leaf3;

// Simulate finding the start leaf (in a real B+ tree this is O(log n))
function findStartLeaf(rootLeaf, targetKey) {
  let leaf = rootLeaf;
  while (leaf && leaf.keys[leaf.keys.length - 1] < targetKey)
    leaf = leaf.next;
  return leaf;
}

// Range query: find all records where 12 <= key <= 42
function rangeQuery(startLeaf, lo, hi) {
  const results = [];
  let   leaf    = findStartLeaf(startLeaf, lo);

  // Walk the linked list of leaves
  while (leaf !== null) {
    for (let i = 0; i < leaf.keys.length; i++) {
      const k = leaf.keys[i];
      if (k > hi) return results; // past the upper bound — stop
      if (k >= lo) results.push({ key: k, record: leaf.records[i] });
    }
    leaf = leaf.next; // O(1) hop to the next leaf
  }
  return results;
}

const hits = rangeQuery(leaf1, 12, 42);
hits.forEach(r => console.log(`key=${r.key} record=${r.record}`));
// key=15 record=carol
// key=20 record=dave
// key=25 record=eve
// key=30 record=frank
// key=35 record=grace
// key=40 record=heidi

// Key insight: once we find the start leaf (O(log n) in real tree),
// the rest of the scan is O(k) where k = number of results.
// No backtracking through internal nodes is needed.
